  from incoming
  order by headword, pos
  on conflict (headword, pos) do update set headword = excluded.headword
  returning id, headword, pos
)
insert into public.senses (word_id, sense_index, definition_en, translation_he, cefr_level,
                           translation_confidence, he_interference_note, he_one_to_many_group,
                           generation_run_id, needs_human_review)
select w.id, i.sense_index, i.definition_en, i.translation_he, i.cefr_level,
       i.translation_confidence, i.he_interference_note, i.he_one_to_many_group,
       run.id, i.needs_human_review
from incoming i
join w on w.headword = i.headword and w.pos = i.pos
cross join run
on conflict (word_id, sense_index) do nothing;

